#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ascauth.h>

/*
 * Retrieves the full membership list for *group* using ASC_GRPMEM.
 * On success returns a newly allocated string that the caller must free.
 * Returns NULL if an unrecoverable error occurs.
 */
char *get_all_group_members(ASCENV *asce, const char *group)
{
    size_t bufsize = 2048;               /* start with 2 KB */
    char *buf = NULL;
    int rc;

    while (1) {
        buf = (char *)realloc(buf, bufsize);
        if (!buf) {
            perror("realloc");
            return NULL;
        }

        rc = ASC_GRPMEM(asce, (char *)group, buf, (u_int)bufsize);
        if (rc == AS_OK) {
            /* Successful full retrieval */
            return buf;
        } else if (rc == AS_TOOSMALL) {
            /* Buffer too small – increase and retry */
            bufsize *= 2;   /* double the size */
            continue;
        } else {
            /* Some other error – report and clean up */
            fprintf(stderr, "ASC_GRPMEM failed: %s\n", ASC_STRERROR(rc));
            free(buf);
            return NULL;
        }
    }
}
